def P(num,h,fig,tier,grant,inv,title,teaches,figs,status="Expired",**k):
    d=dict(num=num,hash=h,fig=fig,tier=tier,grant=grant,inv=inv,title=title,teaches=teaches,figs=figs,status=status); d.update(k); return d
INTRO = "<p>First-aid gear was patented over and over in the 1800s, often by country doctors. These drawings show splints, a crutch, stretchers, an elastic tourniquet and an early two-ear stethoscope, all of which can be made from wood, cloth, rubber or tubing. They end with a plaster splint, a spring syringe and a blood-pressure gauge that need a workshop or factory. They show how the devices are built. They are <b>not medical instructions</b>: follow the bleeding, fracture and splinting chapters of this guide for how to use them.</p>"
UNPATENTED = ["Board-and-cloth splints, a two-pole blanket litter, a forked-branch crutch and a strap-and-stick windlass for bleeding are old common practice. Nobody owns them, so copy them freely."]
PATENTS = [
P("US10909","8b/7f/f5/8688e2968f1140/US10909.pdf","d6/06/13/1cef8118dc3006/US10909-drawings-page-1.png","A","1854-05-16","Smith A. Skinner","Surgical splint (apparatus for fractures of the thigh and leg)",
  "A board splint for a broken thigh or leg from a Vermont maker. Two rest boards are shaped to the back of the thigh and the lower leg, hinged at the knee and strapped on with buckles, on supports that keep the limb still. Copy it in planks and webbing.","Fig. 1 top view; Fig. 2 side elevation; Fig. 3 underside of the hinged rest boards"),
P("US26829","4c/27/45/8b98df65ce1f53/US26829.pdf","a4/f2/93/6463b78c6dfd2b/US26829-drawings-page-1.png","A","1860-01-17","August Bickel","Crutch",
  "A wooden underarm crutch with springs and an elastic strap in the top piece to cushion the armpit, plus a sprung foot. It shows the basic crutch frame (two side pieces, handgrip and crosspiece) that can be made from saplings or boards.","Fig. 1 crutch; Fig. 2 section of the top piece; Figs. 3&ndash;6 the spring parts of the foot", visual=True),
P("US722456","36/b5/b2/8d1b7d8709eaa0/US722456.pdf","ed/03/d5/0ef72ca0f628e6/US722456-drawings-page-1.png","A","1903-03-10","James E. Reeves","Stretcher",
  "A folding fabric stretcher with straps to hold the patient's upper body, arms and legs, and handles made of loops of strong rope. It packs small and is easy to sew from canvas.","Stretcher spread flat with straps and rope handles"),
P("US268407","d4/cd/06/8aadd47d062a1a/US268407.pdf","73/b3/12/aa3099d4995a63/US268407-drawings-page-1.png","A","1882-12-05","Joseph C. Hughes","Surgical tourniquet (elastic tourniquet)",
  "An elastic tourniquet that can be put on quickly, after an accident or during surgery, round a large or small limb to stop severe bleeding. Use a tourniquet only for life-threatening limb bleeding, as the bleeding chapter (Stop the Bleed) describes. Note the time it went on.","Elastic band and its fastening"),
P("US8591","8a/7e/3f/8b2d1fc08eeb10/US8591.pdf","bb/90/53/795afcdf6240de/US8591-drawings-page-1.png","A","1851-12-16","Nathan B. Marsh","Stethoscope (stethoscope and ear trumpet)",
  "A stethoscope with a double branch from one trunk, so the listener puts one branch in each ear. It is the two-ear layout of the modern stethoscope, and it can be made from a funnel and tubing.","Fig. 1 vertical section; Fig. 2 trunk and the two ear branches", visual=True),
P("US39840","8d/48/b7/2dba92e79a08cb/US39840.pdf","aa/0a/b5/471ca083b9eb7e/US39840-drawings-page-1.png","B","1863-09-08","Jacob J. Smith","Improvement in army-stretchers",
  "A Civil War-era army stretcher and cot. Poles carry canvas and are spread by hinged cross-braces, so it opens wide for use and folds flat for carrying in a wagon. It needs carpentry and simple metal fittings.","Fig. 1 underside plan; Figs. 2&ndash;3 end views open and folded", visual=True),
P("US323775","cb/34/41/140aefcdd67a64/US323775.pdf","9b/7f/63/2594f939135bd2/US323775-drawings-page-1.png","B","1885-08-04","John W. Bender &amp; James C. Hinkle","Plaster-of-paris splint",
  "A splint cast in two half-shell sections of plaster of Paris, each moulded to the shape of one side of the limb, with meeting edges so the top half can be lifted for checking the limb and closed again.","Fig. 1 splint detached; Fig. 2 one half in place, other raised"),
P("US159192","a3/92/fd/594f1d82a663eb/US159192.pdf","8e/9d/9a/8e240871b455a1/US159192-drawings-page-1.png","C","1875-01-26","Josef Leiter (Vienna)","Improvement in hypodermic syringes",
  "A spring-driven injector: a small syringe with a needle point inside a tube, and a spring-loaded head that drives the piston quickly when released. It shows how precision syringes are made (fine tubing, a ground piston, a needle). These are factory items. Reuse factory syringes only after proper sterilisation, as the sterilising chapter explains.","Fig. 1 longitudinal section; Fig. 2 side view; Fig. 3 cross-section"),
P("US917276","08/88/e0/32dcc314a95dfd/US917276.pdf","62/62/d4/21412bf07cba14/US917276-drawings-page-1.png","C","1909-04-06","Francis Ashley Faught (assignor to George P. Pilling &amp; Son Co.)","Apparatus for measuring and indicating blood-pressure",
  "A sphygmomanometer (blood-pressure gauge). A closed air system joins a mercury manometer to an arm cuff, and pressure is read when the pulse below the cuff disappears. It is a reference for understanding and repairing old cuff-and-gauge sets.","Manometer, bulb and cuff arrangement"),
P("US276429","4f/00/a8/65e812534235a9/US276429.pdf","1c/a9/c1/188277721a60fd/US276429-drawings-page-1.png","B","1883-04-24","Maximilian J. Koenig","Invalid-chair",
  "Attachments that turn an ordinary chair (shown on a rocking chair) into a wheeled invalid chair. Journal boxes are fixed under the seat; two large wheels on axle stubs pass through them, and a rear wheel turns on a removable upright shaft. Adjustable collars hold the wheels in place, and the parts come off again when not needed.","Fig. 1 side view of the chair with wheels; Fig. 2 front view; Fig. 3 coupling bar"),
P("US446140","23/d4/60/9310effd31f1d4/US446140.pdf","f5/4a/07/286b28af42674a/US446140-drawings-page-1.png","C","1891-02-10","John Wall","Clinical thermometer",
  "A clinical (fever) thermometer with a flat, disk-shaped mercury bulb, so that a large surface of mercury takes up body heat quickly. The disk shape is easy to hold in the mouth or the armpit, and a flat rectangular bulb is described for rectal use. Making one needs glass-blowing, mercury and calibration, so stockpile thermometers rather than plan to make them.","Fig. 1 the thermometer with disk bulb; other figures the bulb shapes"),
]
